function createBoat1Colors(vertices) {
    return Array(vertices.length / 3).fill().flatMap((_, i) => {
        const x = vertices[i * 3];
        const z = vertices[i * 3 + 2];
        const absX = Math.abs(x);

        if (z > 0.29) return [0.08, 0.09, 0.14];
        if (z > 0.18 && absX < 0.18) return [0.90, 0.91, 0.94];
        if (z > 0.12) return [0.76, 0.14, 0.10];
        if (absX > 0.22) return [0.82, 0.84, 0.88];
        return [0.18, 0.20, 0.28];
    });
}

function createBoat2Colors(vertices) {
    return Array(vertices.length / 3).fill().flatMap((_, i) => {
        const x = vertices[i * 3];
        const z = vertices[i * 3 + 2];
        const absX = Math.abs(x);

        if (z > 0.63) return [0.10, 0.10, 0.10];
        if (z > 0.52) return [0.93, 0.93, 0.95];
        if (z > 0.31) return [0.70, 0.73, 0.78];
        if (z < 0.10) return [0.55, 0.16, 0.10];
        if (absX > 0.45) return [0.18, 0.20, 0.28];
        return [0.76, 0.78, 0.82];
    });
}

function createBoat3Colors(vertices) {
    return createBoat4Colors(vertices);
}

function createBoat4Colors(vertices) {
    return Array(vertices.length / 3).fill().flatMap((_, i) => {
        const x = vertices[i * 3];
        const y = vertices[i * 3 + 1];
        const z = vertices[i * 3 + 2];
        const absX = Math.abs(x);

        if (z < 0.22) return [0.62, 0.20, 0.13];
        if (z < 0.72 && absX > 0.55) return [0.08, 0.09, 0.16];
        if (z > 1.55) return [0.11, 0.12, 0.20];
        if (z > 1.22 && absX < 0.55) return [0.84, 0.55, 0.20];
        if (z > 0.95) return [0.92, 0.93, 0.96];
        if (z > 0.70) return [0.82, 0.61, 0.40];
        if (Math.abs(y) > 3.25 && z > 0.45) return [0.82, 0.61, 0.40];
        return [0.88, 0.89, 0.93];
    });
}
